    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (tid, '26. A 32-year-old presents with sudden palpitations, HR 180 bpm, narrow QRS complexes, and a regular rhythm. BP 110/70. What is the first-line treatment?', '["Synchronized cardioversion", "Vagal maneuvers", "IV amiodarone", "Defibrillation"]', 1, 'Hemodynamically stable narrow-complex tachycardia (SVT) is initially managed with vagal maneuvers (Valsalva, carotid sinus massage). If unsuccessful, IV adenosine 6mg rapid push is next.'),
    (tid, '27. A patient with SVT does not respond to vagal maneuvers. IV adenosine 6 mg is given. The rhythm transiently slows then returns to SVT. What is the next step?', '["Adenosine 12 mg IV rapid push", "Synchronized cardioversion", "IV diltiazem", "IV lidocaine"]', 0, 'If 6mg adenosine fails, give 12mg adenosine rapid IV push followed by a saline flush. Adenosine has a half-life of <10 seconds and must be given rapidly through a proximal IV.'),
    (tid, '28. Which ECG finding is pathognomonic for Wolff-Parkinson-White (WPW) syndrome?', '["Delta wave with short PR interval", "Prolonged QT interval", "Epsilon wave", "Osborn J wave"]', 0, 'WPW shows a delta wave (slurred QRS upstroke), short PR interval (<120ms), and wide QRS due to ventricular pre-excitation through an accessory pathway (Bundle of Kent).'),
    (tid, '29. A patient with WPW develops atrial fibrillation with rapid ventricular response. Which medication is CONTRAINDICATED?', '["Procainamide", "Ibutilide", "AV nodal blocking agents (adenosine, diltiazem, verapamil)", "Amiodarone"]', 2, 'AV nodal blockers (adenosine, beta-blockers, calcium channel blockers, digoxin) are contraindicated in WPW with AF because they can enhance conduction through the accessory pathway, causing VF.'),
    (tid, '30. A 65-year-old presents with a wide-complex tachycardia at 160 bpm. BP is 85/60 and he is confused. What is the immediate management?', '["IV amiodarone 150mg", "IV adenosine 6mg", "Synchronized cardioversion", "Unsynchronized defibrillation"]', 2, 'Wide-complex tachycardia with hemodynamic instability (hypotension, altered mental status) requires immediate synchronized cardioversion regardless of whether the rhythm is VT or SVT with aberrancy.'),
    (tid, '31. In a monitored patient, you see a wide-complex tachycardia. What clinical feature most strongly favors ventricular tachycardia over SVT with aberrancy?', '["Heart rate >150 bpm", "AV dissociation", "Regular rhythm", "QRS width of 140ms"]', 1, 'AV dissociation (P waves marching independently of QRS complexes) is virtually diagnostic of VT. Other VT clues: capture beats, fusion beats, concordance in precordial leads, and northwest axis.'),
    (tid, '32. A patient in pulseless ventricular tachycardia is found. What is the correct initial energy dose for defibrillation?', '["50 J synchronized", "120-200 J biphasic unsynchronized", "360 J monophasic synchronized", "100 J biphasic synchronized"]', 1, 'Pulseless VT is treated identically to VF with immediate unsynchronized defibrillation at 120-200J biphasic (or 360J monophasic), followed by CPR and ACLS algorithm.'),
    (tid, '33. During cardiac arrest, which medication is given every 3-5 minutes?', '["Amiodarone 300mg", "Atropine 1mg", "Epinephrine 1mg IV/IO", "Lidocaine 1.5mg/kg"]', 2, 'Epinephrine 1mg IV/IO is given every 3-5 minutes during cardiac arrest for its alpha-1 vasoconstrictor effects, which increase coronary perfusion pressure during CPR.'),
    (tid, '34. After the third defibrillation for refractory VF, which antiarrhythmic should be given?', '["Lidocaine 1mg/kg", "Amiodarone 300mg IV", "Procainamide 20mg/min", "Magnesium 2g IV"]', 1, 'Amiodarone 300mg IV push is the first-line antiarrhythmic for shock-refractory VF/pulseless VT. A second dose of 150mg can be given. Lidocaine is an alternative if amiodarone is unavailable.'),
    (tid, '35. A 78-year-old presents with dizziness and a heart rate of 35 bpm. ECG shows a regular rhythm with P waves that are not associated with QRS complexes. Diagnosis?', '["First-degree AV block", "Second-degree Mobitz type I", "Second-degree Mobitz type II", "Third-degree (complete) heart block"]', 3, 'Complete AV dissociation with a ventricular rate of 35 bpm indicates third-degree heart block. P waves march independently at their own rate while a ventricular escape rhythm maintains perfusion.'),
    (tid, '36. In symptomatic bradycardia, what is the first-line medication?', '["Epinephrine 1mg IV", "Atropine 1mg IV", "Dopamine 5mcg/kg/min", "Isoproterenol"]', 1, 'Atropine 1mg IV (may repeat every 3-5 min, max 3mg) is first-line for symptomatic bradycardia. It blocks vagal tone at the AV node. If ineffective, transcutaneous pacing or dopamine/epinephrine infusion.'),
    (tid, '37. Atropine is least effective in which type of heart block?', '["Sinus bradycardia", "First-degree AV block", "Mobitz type I", "Mobitz type II and third-degree block with wide QRS"]', 3, 'Atropine acts on the AV node (vagal blockade). Mobitz II and infranodal third-degree block originate below the AV node (His-Purkinje), making atropine ineffective. These require pacing.'),
    (tid, '38. A patient with new-onset atrial fibrillation has been in AF for 3 days. HR is controlled at 85 bpm. Before cardioversion, what must be performed?', '["Stress test", "TEE to rule out left atrial thrombus or 3 weeks of anticoagulation", "CT coronary angiography", "Cardiac MRI"]', 1, 'AF >48 hours (or unknown duration) increases risk of atrial thrombus formation. TEE or 3 weeks of therapeutic anticoagulation is required before cardioversion to prevent stroke.'),
    (tid, '39. What is the most common sustained arrhythmia encountered in the emergency department?', '["SVT", "Ventricular tachycardia", "Atrial fibrillation", "Atrial flutter"]', 2, 'Atrial fibrillation is the most common sustained cardiac arrhythmia, affecting 2-3% of the population. Its prevalence increases with age, reaching 10% in those over 80.'),
    (tid, '40. A patient with new atrial fibrillation has a CHA2DS2-VASc score of 4. What does this indicate?', '["Low bleeding risk", "High stroke risk requiring anticoagulation", "Need for rate control only", "Indication for ablation"]', 1, 'CHA2DS2-VASc ≥2 in males or ≥3 in females indicates high stroke risk and warrants long-term oral anticoagulation (DOACs preferred over warfarin) to prevent thromboembolic events.'),
    (tid, '41. Which ECG pattern is characteristic of atrial flutter?', '["Irregularly irregular rhythm", "Sawtooth flutter waves at ~300/min with 2:1 block", "Diffuse ST elevation", "Delta waves"]', 1, 'Atrial flutter shows regular sawtooth (F) waves at ~300 bpm, typically with 2:1 AV conduction giving a ventricular rate of ~150 bpm. Best seen in leads II, III, aVF, and V1.'),
    (tid, '42. A patient presents with a regular narrow-complex tachycardia at exactly 150 bpm. What diagnosis should be considered until proven otherwise?', '["Sinus tachycardia", "Atrial flutter with 2:1 block", "SVT", "Junctional tachycardia"]', 1, 'A regular narrow-complex tachycardia at exactly 150 bpm is atrial flutter with 2:1 block until proven otherwise. Adenosine can be used diagnostically to unmask flutter waves.'),
    (tid, '43. Torsades de Pointes (TdP) is associated with which underlying ECG abnormality?', '["Short QT interval", "Prolonged QT interval", "ST elevation", "PR prolongation"]', 1, 'TdP is a polymorphic VT occurring in the context of prolonged QT interval. It can be congenital or acquired (drugs: antiarrhythmics, antibiotics, antipsychotics; electrolyte abnormalities).'),
    (tid, '44. What is the first-line treatment for Torsades de Pointes?', '["Amiodarone 300mg IV", "Magnesium sulfate 2g IV", "Lidocaine 1mg/kg", "Synchronized cardioversion"]', 1, 'IV magnesium sulfate 2g over 1-2 minutes is first-line for TdP regardless of serum magnesium level. It stabilizes the myocardial membrane. Overdrive pacing or isoproterenol can also be used.'),
    (tid, '45. Which electrolyte abnormality most commonly precipitates cardiac arrhythmias?', '["Hypocalcemia", "Hypokalemia", "Hyponatremia", "Hypophosphatemia"]', 1, 'Hypokalemia is the most common electrolyte cause of arrhythmias. It causes U waves, flattened T waves, ST depression, and predisposes to VT/VF. Common in diuretic use and GI losses.'),
    (tid, '46. A patient on digoxin presents with nausea, yellow-tinted vision, and a heart rate of 40 bpm with irregular rhythm. ECG shows atrial tachycardia with variable block. What is the antidote?', '["Calcium gluconate", "Digoxin immune Fab (Digibind)", "Glucagon", "Sodium bicarbonate"]', 1, 'Digoxin toxicity classically presents with GI symptoms, visual disturbances (xanthopsia), and arrhythmias. Digoxin-specific antibody fragments (Fab) bind free digoxin and are the definitive treatment.'),
    (tid, '47. Which rhythm requires unsynchronized defibrillation rather than synchronized cardioversion?', '["Atrial fibrillation with rapid ventricular response", "Ventricular fibrillation", "Monomorphic ventricular tachycardia with pulse", "Atrial flutter"]', 1, 'VF and pulseless VT require unsynchronized defibrillation because there is no organized QRS complex for the defibrillator to synchronize with. All other tachyarrhythmias with a pulse use synchronized cardioversion.'),
    (tid, '48. A patient with a pacemaker presents with chest pain. ECG shows pacemaker spikes not followed by QRS complexes. What is this called?', '["Failure to sense", "Failure to capture", "Oversensing", "Lead fracture with appropriate function"]', 1, 'Failure to capture occurs when the pacemaker fires (spike visible) but fails to depolarize the myocardium (no QRS follows). Causes include lead displacement, battery depletion, elevated capture threshold, or lead fracture.'),
    (tid, '49. An ICD patient presents after receiving multiple appropriate shocks for recurrent VT. HR is 130, BP 100/60. After IV amiodarone, what is the next step?', '["Disable the ICD", "Emergent catheter ablation referral", "Increase amiodarone dose", "Discharge with follow-up"]', 1, 'VT storm (≥3 episodes of sustained VT or appropriate ICD shocks within 24 hours) refractory to antiarrhythmics requires urgent catheter ablation. Sedation and sympathetic blockade may temporize.'),
    (tid, '50. Electrical alternans on ECG (beat-to-beat QRS amplitude variation) in the setting of hypotension and tachycardia is most suggestive of what diagnosis?', '["Large pericardial effusion with tamponade", "Tension pneumothorax", "Massive PE", "Severe aortic stenosis"]', 0, 'Electrical alternans (alternating QRS amplitude) combined with low voltage and sinus tachycardia is highly specific for large pericardial effusion and impending cardiac tamponade.');
